  /^  # Like raw_status, but also returns the response body/ { skipping=1; next }
  skipping && /^  end$/ { skipping=2; next }
  skipping==2 && /^$/ { skipping=0; next }
  skipping { next }
  { print }
' test/server_process_test.rb > /tmp/spt1.rb \
&& awk 'FNR==NR { helper = helper $0 "\n"; next } /^  def free_port$/ { printf "%s", helper } { print }' /tmp/proc_helper.rb /tmp/spt1.rb > test/server_process_test.rb \
&& sed -n '/# Like raw_status/,/^  def free_port$/p' test/server_process_test.rb | cat -A | grep -c '\\r\\n' \
&& grep -c $'\r' test/server_process_test.rb lib/syncbox/server/blob_store.rb test/blob_store_test.rb test/app_test.rb

